// @emotion/server uses html-tokenize which requires Node's Buffer.
// In Vitest browser mode, Buffer is not available, so we provide a no-op shim.
export default {};
export const renderStylesToString = (html: string) => html;
export const renderStylesToNodeStream = () => {
  throw new Error("renderStylesToNodeStream is not available in the browser");
};
export const extractCritical = (html: string) => ({
  html,
  css: "",
  ids: [] as string[],
});
export const extractCriticalToChunks = (html: string) => ({
  html,
  styles: [] as { key: string; ids: string[]; css: string }[],
});

