 1→import React, {
 2→  useEffect,
 3→  useRef,
 4→  ForwardRefExoticComponent,
 5→  RefAttributes,
 6→} from "react";
 7→
 8→interface AnimatedIconProps {
 9→  icon: ForwardRefExoticComponent<
10→    RefAttributes<SVGSVGElement> & {
11→      onMouseEnter?: () => void;
12→      onMouseLeave?: () => void;
13→    }
14→  >;
15→  alwaysAnimate?: boolean;
16→}
17→
18→/**
19→ * `AnimatedIcon` is a component that wraps an SVG icon and adds mouse enter and mouse leave events to pause and unpause animations.
20→ * @param props - The props for the `AnimatedIcon` component.
21→ * @param props.icon - The SVG icon to animate.
22→ * @param props.alwaysAnimate - Whether the icon should always animate or not. Defaults to false.
23→ * @returns - A React component that wraps an SVG icon and adds mouse enter and mouse leave events to pause and unpause animations.
24→ */
25→const AnimatedIcon: React.FC<AnimatedIconProps> = ({
26→  alwaysAnimate = false,
27→  icon,
28→  ...rest
29→}) => {
30→  const iconRef = useRef<SVGSVGElement>(null);
31→  // Animations should be paused by default on page load.
32→  useEffect(() => {
33→    // Check if the SVG has animations before pausing them.
34→    // This is necessary because some SVGs may not have animations.
35→    //  and calling pauseAnimations on an SVG without animations will throw an error.
36→    if (iconRef.current && hasAnimations(iconRef.current) && !alwaysAnimate) {
37→      iconRef.current?.pauseAnimations();
38→    }
39→  }, [alwaysAnimate]);
40→
41→  const onMouseEnter = () => {
42→    if (hasAnimations(iconRef.current!) && !alwaysAnimate) {
43→      iconRef.current?.unpauseAnimations();
44→    }
45→  };
46→
47→  const onMouseLeave = () => {
48→    if (hasAnimations(iconRef.current!) && !alwaysAnimate) {
49→      iconRef.current?.pauseAnimations();
50→    }
51→  };
52→
53→  const Icon = icon;
54→  return (
55→    <Icon
56→      ref={iconRef}
57→      onMouseEnter={onMouseEnter}
58→      onMouseLeave={onMouseLeave}
59→      {...rest}
60→    />
61→  );
62→};
63→
64→/**
65→ * `hasAnimations` checks if an SVG element has animations. This is used to determine if the SVG can be paused and unpaused.
66→ * @param svgElement - The SVG element to check for animations.
67→ * @returns - A boolean indicating if the SVG element has animations.
68→ */
69→const hasAnimations = (svgElement: SVGSVGElement): boolean =>
70→  svgElement.querySelector("animate, animateTransform, animateMotion") !== null;
71→
72→export default AnimatedIcon;
73→

 1→import { useRef, useState } from "react";
 2→import styled from "@emotion/styled";
 3→import { GuideCue, GuideCueProps } from "@leafygreen-ui/guide-cue";
 4→import { palette } from "@leafygreen-ui/palette";
 5→import { differenceInDays } from "date-fns";
 6→import Cookies from "js-cookie";
 7→import { size } from "../../constants/tokens";
 8→import Icon from "../Icon";
 9→
10→type Props = {
11→  activeDays?: number;
12→  cookieName: string;
13→  loading?: boolean;
14→};
15→
16→/**
17→ * ExpiringAnnouncementTooltip displays a clickable info icon with a popover.
18→ * On first view, the popover opens automatically. Once dismissed, a cookie is set
19→ * and the popover stays closed on future visits. The info icon remains visible
20→ * for `activeDays` (default 8) after first dismissal, then disappears entirely.
21→ * @param props - React props
22→ * @param props.activeDays - number of days the info icon will persist after the tooltip is first viewed
23→ * @param props.cookieName - cookie associated with the view state
24→ * @param props.loading - whether data present in the tooltip is loading, helps avoid flickering tooltip
25→ * @returns React component
26→ */
27→export const ExpiringAnnouncementTooltip: React.FC<
28→  Props & Pick<GuideCueProps, "children" | "title" | "tooltipAlign">
29→> = ({ activeDays = 8, cookieName, loading = false, ...guideCueProps }) => {
30→  const now = new Date();
31→  const infoRef = useRef(null);
32→
33→  const seenTooltipCookie: string | undefined = Cookies.get(cookieName);
34→  const neverSeenTooltip = !seenTooltipCookie;
35→  const seenTooltipDate = seenTooltipCookie ? new Date(seenTooltipCookie) : now;
36→
37→  const [open, setOpen] = useState(neverSeenTooltip);
38→
39→  const close = () => {
40→    setOpen(false);
41→
42→    if (neverSeenTooltip) {
43→      Cookies.set(cookieName, seenTooltipDate.toString(), { expires: 365 });
44→    }
45→  };
46→
47→  return !loading &&
48→    (neverSeenTooltip ||
49→      differenceInDays(now, seenTooltipDate) < activeDays) ? (
50→    <>
51→      <IconContainer ref={infoRef}>
52→        <Icon
53→          data-cy="announcement-tooltip-trigger"
54→          fill={palette.gray.dark2}
55→          glyph="InfoWithCircle"
56→          onClick={() => setOpen((o) => !o)}
57→        />
58→      </IconContainer>
59→      <GuideCue
60→        currentStep={1}
61→        numberOfSteps={1}
62→        onDismiss={close}
63→        onPrimaryButtonClick={close}
64→        open={open}
65→        refEl={infoRef}
66→        setOpen={setOpen}
67→        {...guideCueProps}
68→      />
69→    </>
70→  ) : null;
71→};
72→
73→const IconContainer = styled.div`
74→  cursor: pointer;
75→  padding-left: ${size.xxs};
76→`;
