 1→import { getUserStagingKey, isStaging } from "../environmentVariables";
 2→
 3→/**
 4→ * getUserStagingHeader generates the correct headers for the Evergreen-Multi staging backend to correctly route requests.
 5→ * @returns - an object with a key-value pair if the headers should be applied, and an empty object if not.
 6→ */
 7→export const getUserStagingHeader = (): {
 8→  "X-Evergreen-Environment"?: string;
 9→} => {
10→  if (!isStaging()) {
11→    return {};
12→  }
13→
14→  const key = getUserStagingKey();
15→  if (!key) {
16→    return {};
17→  }
18→
19→  return { "X-Evergreen-Environment": key };
20→};
21→
22→export const shouldLogoutAndRedirect = (statusCode: number) =>
23→  statusCode === 401;
24→
25→const getErrorMessage = (response: Response, method: string) => {
26→  const { status, statusText } = response;
27→  return `${method} Error: ${status} - ${statusText}`;
28→};
29→
30→export const fetchWithRetry = <T = unknown>(
31→  url: string,
32→  options: RequestInit,
33→  retries: number = 3,
34→  backoff: number = 150,
35→): Promise<{ data: T }> =>
36→  new Promise((resolve, reject) => {
37→    const attemptFetch = (attempt: number): void => {
38→      fetch(url, options)
39→        .then((res) => {
40→          if (res.ok) {
41→            return res.json();
42→          }
43→          reject(
44→            new Error(getErrorMessage(res, "GET"), {
45→              cause: { message: res.statusText, statusCode: res.status },
46→            }),
47→          );
48→        })
49→        .then((data) => resolve(data))
50→        .catch((err) => {
51→          if (attempt <= retries) {
52→            setTimeout(() => attemptFetch(attempt + 1), backoff * attempt);
53→          } else {
54→            reject(err);
55→          }
56→        });
57→    };
58→    attemptFetch(1);
59→  });
60→

 1→import {
 2→  PAGE_SIZES,
 3→  DEFAULT_PAGE_SIZE,
 4→  RECENT_PAGE_SIZE_KEY,
 5→} from "../../constants/pagination";
 6→
 7→/**
 8→ * Returns the most recent page size from local storage or the default page size
 9→ * @returns The recent or default page size
10→ */
11→export const getDefaultPageSize = () => {
12→  const pageSizeFromLocalStorage = localStorage.getItem(RECENT_PAGE_SIZE_KEY);
13→  const pageSize = pageSizeFromLocalStorage
14→    ? parseInt(pageSizeFromLocalStorage, 10)
15→    : DEFAULT_PAGE_SIZE;
16→
17→  return PAGE_SIZES.includes(pageSize) ? pageSize : DEFAULT_PAGE_SIZE;
18→};
